def inventory_summary(records, category):
    names = []
    units = 0
    for record in records:
        if record["category"] == category:
            names.append(record["name"])
            units = units + record["quantity"]
    return {"items": len(names), "units": units, "names": names}

print(inventory_summary([{'name': 'Cable', 'category': 'Comms', 'quantity': 3}, {'name': 'Pen', 'category': 'Desk', 'quantity': 2}, {'name': 'Radio', 'category': 'Comms', 'quantity': 1}], 'Comms'))
